import React, { useState, useEffect } from "react";
import "../styles/ImageCarousel.css";

function ImageCarousel() {
  const [currentIndex, setCurrentIndex] = useState(0);

  const images = [
    {
      src: "../assets/images/image.png",
      alt: "Modern Fashion",
      subtitle: "Pour chaque occasion",
      title: "Style Moderne",
    },
    {
      src: "../assets/images/img2.png",
      alt: "Evening Gown",
      subtitle: "Sophistication Intemporelle",
      title: "Tenue de Soirée",
    },
    {
      src: "../assets/images/img3.png",
      alt: "Elegant Collection",
      subtitle: "Nouvelle Arrivée 2025",
      title: "Collection Élégance",
    },
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentIndex((current) => (current + 1) % 3);
    }, 2000);

    return () => clearInterval(interval);
  }, []);

  const goToPrevious = () => {
    setCurrentIndex((current) => (current === 0 ? 2 : current - 1));
  };

  const goToNext = () => {
    setCurrentIndex((current) => (current + 1) % 3);
  };

  return (
    <div className="carousel-container">
      <div className="carousel">
        <img
          src={images[currentIndex].src}
          alt={images[currentIndex].alt}
          className="carousel-image"
          key={currentIndex}
        />

        <div className="image-overlay">
          <p className="image-subtitle">{images[currentIndex].subtitle}</p>
          <h2 className="image-title">{images[currentIndex].title}</h2>
          <button className="discover-btn">Découvrir →</button>
        </div>

        <button
          onClick={goToPrevious}
          className="carousel-btn carousel-btn-left"
        >
          <svg
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
          >
            <path d="M15 18l-6-6 6-6" />
          </svg>
        </button>

        <button onClick={goToNext} className="carousel-btn carousel-btn-right">
          <svg
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
          >
            <path d="M9 18l6-6-6-6" />
          </svg>
        </button>

        <div className="carousel-indicators">
          {[0, 1, 2].map((index) => (
            <button
              key={index}
              onClick={() => setCurrentIndex(index)}
              className={`indicator ${index === currentIndex ? "active" : ""}`}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

export default ImageCarousel;
